/** Safe lookup for a town with no CATEGORY_IMAGES entry at all (e.g. a
 *  newly-added town before its images are generated) -- every call site
 *  used to index CATEGORY_IMAGES[townId] directly with no fallback, which
 *  is `undefined` for an unlisted key and crashes resolveImage() with a
 *  raw TypeError (`undefined[category]`) instead of degrading to "no
 *  image" the way the rest of that function is designed to. */
export function categoryImagesFor(townId: string): Partial<Record<ImageCategory, ImageRef[]>> {
  return CATEGORY_IMAGES[townId as Town] ?? {};
}
